// Definições de tipos para o sistema de orçamentos

export enum Salesperson {
  NAQUELINE = 'NAQUELINE',
  MYLENA = 'MYLENA',
  YASMIN = 'YASMIN',
  UNSELECTED = ''
}

export interface BudgetItem {
  id: string;
  itemNumber: number;
  description: string;
  quantity: number;
  unitPrice: number;
  discountPercent: number;
  total: number;
}

export interface ClientInfo {
  name: string;
  document: string; // CPF ou CNPJ
  address: string;
  email: string;
  phone: string;
  architect: string;
  salesperson: Salesperson | string;
  notes: string;
}

export interface Budget {
  id: string; // O código de 6 dígitos (ex: A12345)
  createdAt: number;
  lastModified: number;
  client: ClientInfo;
  items: BudgetItem[];
  globalDiscountPercent: number;
}

// Interface para exportação/importação
export interface BudgetBackup {
  version: number;
  data: Budget[];
}

import { Budget } from './types';

// Gera um ID de orçamento no formato: 1 Letra maiúscula e 5 Números (Posição aleatória)
export const generateBudgetNumber = (existingBudgets: Budget[]): string => {
  const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const numbers = '0123456789';

  let newId = '';
  let isUnique = false;

  while (!isUnique) {
    const letter = letters.charAt(Math.floor(Math.random() * letters.length));
    const nums = Array.from({ length: 5 }, () => numbers.charAt(Math.floor(Math.random() * numbers.length)));

    // Insere a letra em uma posição aleatória (0 a 5)
    const position = Math.floor(Math.random() * 6);
    nums.splice(position, 0, letter);

    newId = nums.join('');

    // Verifica conflito
    if (!existingBudgets.some(b => b.id === newId)) {
      isUnique = true;
    }
  }

  return newId;
};

// Formata moeda para BRL
export const formatCurrency = (value: number): string => {
  return new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL',
  }).format(value);
};

// Máscara para CPF/CNPJ
export const maskDocument = (value: string): string => {
  const clean = value.replace(/\D/g, '');
  if (clean.length <= 11) {
    // CPF
    return clean
      .replace(/(\d{3})(\d)/, '$1.$2')
      .replace(/(\d{3})(\d)/, '$1.$2')
      .replace(/(\d{3})(\d{1,2})/, '$1-$2')
      .replace(/(-\d{2})\d+?$/, '$1');
  } else {
    // CNPJ
    return clean
      .replace(/(\d{2})(\d)/, '$1.$2')
      .replace(/(\d{3})(\d)/, '$1.$2')
      .replace(/(\d{3})(\d)/, '$1/$2')
      .replace(/(\d{4})(\d)/, '$1-$2')
      .replace(/(-\d{2})\d+?$/, '$1');
  }
};

// Máscara para Telefone (xx) x xxxx-xxxx
export const maskPhone = (value: string): string => {
  const clean = value.replace(/\D/g, '');
  return clean
    .replace(/^(\d{2})(\d)/g, '($1) $2')
    .replace(/(\d)(\d{4})$/, '$1-$2')
    .slice(0, 16); // Limita tamanho
};

// Gera ID único para itens
export const generateUUID = (): string => {
  return Date.now().toString(36) + Math.random().toString(36).substr(2);
};

import React, { useEffect, useState, useRef } from 'react';
