import React, { useState, useEffect } from 'react';
import { Plus, Search, FileJson, Upload, Layout, Lightbulb, Save } from 'lucide-react';
import BudgetForm from './components/BudgetForm';
import { Budget, BudgetBackup, Salesperson } from './types';
import { generateBudgetNumber } from './utils';

const App: React.FC = () => {
  // Inicialização Lazy do estado para evitar sobrescrever o LocalStorage ao recarregar
  const [budgets, setBudgets] = useState<Budget[]>(() => {
    const stored = localStorage.getItem('luz_budgets');
    try {
      return stored ? JSON.parse(stored) : [];
    } catch (e) {
      console.error("Erro ao carregar dados", e);
      return [];
    }
  });

  const [activeBudgetId, setActiveBudgetId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [showDataMsg, setShowDataMsg] = useState(true);

  // Se houver orçamentos mas nenhum ativo (ex: após refresh), ativa o primeiro
  useEffect(() => {
    if (budgets.length > 0 && !activeBudgetId) {
      setActiveBudgetId(budgets[0].id);
    }
  }, []); // Executa apenas na montagem inicial se necessário

  // Persistência (Save to LocalStorage)
  useEffect(() => {
    localStorage.setItem('luz_budgets', JSON.stringify(budgets));
  }, [budgets]);

  // Mensagem temporária de armazenamento
  useEffect(() => {
    const timer = setTimeout(() => setShowDataMsg(false), 8000);
    return () => clearTimeout(timer);
  }, []);

  const createNewBudget = () => {
    const newId = generateBudgetNumber(budgets);
    const newBudget: Budget = {
      id: newId,
      createdAt: Date.now(),
      lastModified: Date.now(),
      client: {
        name: '',
        document: '',
        address: '',
        email: '',
        phone: '',
        architect: '',
        salesperson: Salesperson.UNSELECTED,
        notes: ''
      },
      items: [],
      globalDiscountPercent: 0,
      shippingCost: 0,
      otherExpenses: 0
    };

    setBudgets(prev => [newBudget, ...prev]);
    setActiveBudgetId(newId);
    setSearchTerm(''); // Limpa busca ao criar novo
  };

  const handleUpdateBudget = (updated: Budget) => {
    setBudgets(prev => prev.map(b => b.id === updated.id ? updated : b));
  };

  const handleDeleteBudget = (id: string) => {
    if (confirm('Tem certeza que deseja excluir este orçamento? Esta ação não pode ser desfeita.')) {
      const newBudgets = budgets.filter(b => b.id !== id);
      setBudgets(newBudgets);
      if (activeBudgetId === id) {
        setActiveBudgetId(newBudgets.length > 0 ? newBudgets[0].id : null);
      }
    }
  };

  const exportAllData = () => {
    const backup: BudgetBackup = { version: 1, data: budgets };
    const blob = new Blob([JSON.stringify(backup, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `backup_completo_luz_${new Date().toISOString().slice(0,10)}.json`;
    a.click();
  };

  const importData = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;

        // Tenta detectar se é um backup completo ou um orçamento único
        const parsed = JSON.parse(content);

        let newBudgetsList = [...budgets];
        let importedCount = 0;

        if (parsed.version && Array.isArray(parsed.data)) {
          // É um backup completo
          const backup = parsed as BudgetBackup;
          backup.data.forEach(importedBudget => {
            const index = newBudgetsList.findIndex(b => b.id === importedBudget.id);
            if (index >= 0) {
              newBudgetsList[index] = importedBudget;
            } else {
              newBudgetsList.push(importedBudget);
            }
            importedCount++;
          });
        } else if (parsed.id && parsed.client) {
           // É um orçamento único
           const singleBudget = parsed as Budget;
           const index = newBudgetsList.findIndex(b => b.id === singleBudget.id);
            if (index >= 0) {
              if(confirm(`Já existe um orçamento com o ID ${singleBudget.id}. Deseja sobrescrevê-lo?`)) {
                newBudgetsList[index] = singleBudget;
                importedCount++;
              }
            } else {
              newBudgetsList.unshift(singleBudget); // Adiciona no início
              importedCount++;
              setActiveBudgetId(singleBudget.id);
            }
        }

        setBudgets(newBudgetsList);
        if (importedCount > 0) {
          alert(`${importedCount} orçamento(s) importado(s) com sucesso!`);
        } else {
          alert('Nenhum dado novo foi importado.');
        }

      } catch (err) {
        alert('Erro ao ler arquivo JSON. Verifique o formato.');
        console.error(err);
      }
      // Limpa o input para permitir importar o mesmo arquivo novamente se necessário
      event.target.value = '';
    };
    reader.readAsText(file);
  };

  // Lógica de Filtro Aprimorada
  const filteredBudgets = budgets.filter(b => {
    const search = searchTerm.toUpperCase().trim();
    if (!search) return true;

    return (
      (b.client.name && b.client.name.toUpperCase().includes(search)) ||
      (b.client.phone && b.client.phone.replace(/\D/g, '').includes(search.replace(/\D/g, ''))) ||
      (b.id && b.id.includes(search)) ||
      (b.client.document && b.client.document.includes(search))
    );
  });

  const activeBudget = budgets.find(b => b.id === activeBudgetId);

  return (
    <div className="flex flex-col h-screen bg-gray-100">

      {/* Barra Superior */}
      <div className="bg-gray-900 text-white shadow-md no-print z-10 flex-shrink-0">
        <div className="max-w-7xl mx-auto px-4">
          <div className="flex items-center justify-between h-16 gap-4">

            {/* Logo area */}
            <div className="flex items-center gap-3 flex-shrink-0">
              <div className="bg-white text-black p-1.5 rounded">
                <Lightbulb size={20} className="fill-current" />
              </div>
              <span className="font-bold text-lg tracking-wider hidden md:block">LUZ GESTÃO</span>
            </div>

            {/* Busca */}
            <div className="flex-1 max-w-2xl">
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Search size={16} className="text-gray-400" />
                </div>
                <input
                  type="text"
                  className="block w-full pl-10 pr-3 py-2 border border-transparent rounded-md leading-5 bg-gray-800 text-gray-300 placeholder-gray-500 focus:outline-none focus:bg-gray-700 focus:border-gray-600 focus:text-white sm:text-sm transition duration-150 ease-in-out"
                  placeholder="Buscar por Cliente, CPF/CNPJ, Telefone ou Nº..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
              </div>
            </div>

            {/* Ações Globais */}
            <div className="flex items-center gap-2 flex-shrink-0">
              <label className="p-2 text-gray-400 hover:text-white cursor-pointer rounded hover:bg-gray-800 transition-colors" title="Importar JSON (Backup ou Individual)">
                <Upload size={20} />
                <input type="file" accept=".json" onChange={importData} className="hidden" />
              </label>
              <button onClick={exportAllData} className="p-2 text-gray-400 hover:text-white rounded hover:bg-gray-800 transition-colors" title="Backup Completo (Todos os Orçamentos)">
                <Save size={20} />
              </button>
            </div>
          </div>
        </div>

        {/* Aviso de LocalStorage */}
        {showDataMsg && (
