            </p>
            {budgets.length === 0 && (
              <button 
                onClick={createNewBudget}
                className="mt-4 px-6 py-2 bg-indigo-600 text-white rounded shadow hover:bg-indigo-700 transition-colors"
              >
                Criar Primeiro Orçamento
              </button>
            )}
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

