      </div>

      {/* Canhoto de Entrega (Stub) - Compacto em uma linha */}
      <div className="mt-2 pt-4 border-t border-dashed border-gray-400 print:mt-auto print:pt-4 print:break-inside-avoid w-full">
        <div className="flex items-end justify-between gap-4 text-[9px] font-bold uppercase text-gray-600">
            {/* Texto de Recebimento */}
            <span className="shrink-0 pb-0.5">Recebemos de LUZ ILUMINAÇÃO os produtos deste pedido</span>

            {/* Data */}
            <div className="flex items-end gap-1 shrink-0">
               <span className="pb-0.5">Data:</span>
               <span className="text-xs font-normal tracking-widest text-black">___/___/______</span>
            </div>

            {/* Assinatura */}
            <div className="flex items-end gap-1 flex-1">
               <span className="pb-0.5 shrink-0">Assinatura:</span>
               <div className="border-b border-black flex-1"></div>
            </div>

             {/* Número do Pedido */}
             <div className="flex items-end gap-1 shrink-0 pb-0.5">
                 <span>Nº Pedido:</span>
                 <span className="text-sm font-bold text-black leading-none">{localBudget.id}</span>
             </div>
        </div>
      </div>

      {/* Botões de Ação Fixos */}
      <div className="mt-12 flex justify-end gap-3 border-t border-gray-200 pt-6 no-print">
        <button 
            onClick={() => onDelete(localBudget.id)}
            className="flex items-center gap-2 px-4 py-2 text-red-600 hover:bg-red-50 rounded transition-colors text-sm font-medium"
        >
            <Trash2 size={16} />
            Excluir
        </button>
        <div className="flex-1"></div>
        <button 
            onClick={handleExportJSON}
            className="flex items-center gap-2 px-4 py-2 bg-gray-100 text-gray-700 hover:bg-gray-200 border border-gray-300 rounded transition-all shadow-sm text-sm font-medium"
            title="Salvar arquivo .json deste orçamento"
        >
            <FileDown size={16} />
            Baixar JSON
        </button>
        <button 
            onClick={handlePrint}
            className="flex items-center gap-2 px-6 py-2 bg-gray-900 text-white hover:bg-black rounded transition-all shadow-lg text-sm font-medium"
        >
            <Printer size={16} />
            Imprimir / PDF
        </button>
      </div>

    </div>
  );
};

export default BudgetForm;
